import React from 'react';

export default function CategoryPanel({ categories, active, onPick }) {
  return (
    <div className="panel">
      <div className="panel-title">Categories</div>
      <ul className="cat-list">
        {categories.map(c => (
          <li key={c.name}>
            <button
              className={'cat-link ' + (active === c.name ? 'on' : '')}
              onClick={() => onPick(c.name)}
            >
              <span>{c.name}</span>
              <span className="cat-count">{c.count}</span>
            </button>
          </li>
        ))}
      </ul>
    </div>
  );
}
